(56775, 1359, 441, '<td valign="top">good image overcropped, post a question if you have a cropping problem.</td>', 'good image overcropped, post a question if you have a cropping problem.', '2002-05-06 17:12:00.000000', NULL, 1),
(56776, 1359, 1040, '<td valign="top">Where''s the head?</td>', 'Where''s the head?', '2002-05-06 06:22:00.000000', NULL, 1),
(56777, 1359, 1024, '<td valign="top">The timing of this shot wou;d have been better if you caught a few bubbles or some foam.</td>', 'The timing of this shot wou;d have been better if you caught a few bubbles or some foam.', '2002-05-06 09:33:00.000000', NULL, 1),
(56778, 1359, 1175, '<td valign="top">Bad beer.  Good picture. ;)  Cropped just a tad too tight.</td>', 'Bad beer.  Good picture. ;)  Cropped just a tad too tight.', '2002-05-06 10:41:00.000000', NULL, 1),
(56779, 1359, 772, '<td valign="top">Dos Cervesas, por favor :)  This is a nice shot.  I would definitely like it better if the bottle and the bottom of the glass were not cropped out...</td>', 'Dos Cervesas, por favor :)  This is a nice shot.  I would definitely like it better if the bottle and the bottom of the glass were not cropped out...', '2002-05-06 10:53:00.000000', NULL, 1),
(56780, 1359, 327, '<td valign="top">Clear, clean shot with nice light. Your ''head'' has gone flat! Nice set up.</td>', 'Clear, clean shot with nice light. Your ''head'' has gone flat! Nice set up.', '2002-05-06 10:55:00.000000', NULL, 1),
(56781, 1359, 1135, '<td valign="top">The picture is tipping to the left and you croped off part of the bottle and glass. The exposure and lighting are very nice.</td>', 'The picture is tipping to the left and you croped off part of the bottle and glass. The exposure and lighting are very nice.', '2002-05-06 11:41:00.000000', NULL, 1),
(56782, 1359, 885, '<td valign="top">Why did you choose to not include the very top and bottom of the bottle?</td>', 'Why did you choose to not include the very top and bottom of the bottle?', '2002-05-06 12:51:00.000000', NULL, 1),
(56783, 1359, 156, '<td valign="top">very nice ...except for the cropping and tilt of which i''m sure you''re aware</td>', 'very nice ...except for the cropping and tilt of which i''m sure you''re aware', '2002-05-06 14:35:00.000000', NULL, 1),
(56784, 1359, 1005, '<td valign="top">It''s a beer advertisement.  (Did you drink some first?)  Nothing wrong with your photo, among the better beer adverts, but.....Alcohol is supposed to "fun", <br/>where''s the fun part?  Photo 10 Advert 9 Creativity 7 total 8</td>', 'It''s a beer advertisement.  (Did you drink some first?)  Nothing wrong with your photo, among the better beer adverts, but.....Alcohol is supposed to "fun", where''s the fun part?  Photo 10 Advert 9 Creativity 7 total 8', '2002-05-06 14:35:00.000000', NULL, 1),
(56785, 1359, 1204, '<td valign="top">Kind of dull - and the beer looks flat.  Nothing wrong with the pic - but nothing interesting either.  4.</td>', 'Kind of dull - and the beer looks flat.  Nothing wrong with the pic - but nothing interesting either.  4.', '2002-05-06 16:05:00.000000', NULL, 1),
