(56787, 1359, 1336, '<td valign="top">this is pretty good, but you cut the bottom and top of the michelob bottle out of the photo.</td>', 'this is pretty good, but you cut the bottom and top of the michelob bottle out of the photo.', '2002-05-07 00:04:00.000000', NULL, 1),
(56788, 1359, 1037, '<td valign="top">The brand name is repeated too many times here, alongside eveyr possible beer ad cliche... it''s not very nicely composed or framed.</td>', 'The brand name is repeated too many times here, alongside eveyr possible beer ad cliche... it''s not very nicely composed or framed.', '2002-05-07 04:20:00.000000', NULL, 1),
