(56800, 1359, 554, '<td valign="top">nice arangement</td>', 'nice arangement', '2002-05-11 08:07:00.000000', NULL, 1),
(56801, 1359, 1202, '<td valign="top">Good exposure and great color.   I think it is cropped a little tight, nut with the constraints it may have been difficult to get whole bottle and glass.   Sells the product though.</td>', 'Good exposure and great color.   I think it is cropped a little tight, nut with the constraints it may have been difficult to get whole bottle and glass.   Sells the product though.', '2002-05-12 18:42:00.000000', NULL, 1),
