(56829, 1361, 142, '<td valign="top">There is a little too much glare on the cd cover.  Nicely set up though.</td>', 'There is a little too much glare on the cd cover.  Nicely set up though.', '2002-05-11 13:13:00.000000', NULL, 1),
(56830, 1361, 587, '<td valign="top">I don''t follow this ad very well. Are you selling Linkin Park cd''s or just cd''s in general?  In either case I would have made other titles readable also. More lighting and less shadow would help too.</td>', 'I don''t follow this ad very well. Are you selling Linkin Park cd''s or just cd''s in general?  In either case I would have made other titles readable also. More lighting and less shadow would help too.', '2002-05-12 20:07:00.000000', NULL, 1),
(56831, 1361, 1, '<td valign="top">Such a great CD, such not a great advertisement for it though.  I think the CD case by itself (without the others) on a nice background, laid down, with maybe the cd not set in the case, but outside of it...eh...</td>', 'Such a great CD, such not a great advertisement for it though.  I think the CD case by itself (without the others) on a nice background, laid down, with maybe the cd not set in the case, but outside of it...eh...', '2002-05-12 21:35:00.000000', NULL, 1),
(56832, 1363, 1204, '<td valign="top">Although the background is good and fitting the subject, a bit more light from the front would have added more detail.</td>', 'Although the background is good and fitting the subject, a bit more light from the front would have added more detail.', '2002-05-06 16:21:00.000000', NULL, 1),
(56833, 1363, 1226, '<td valign="top">Very nice lightng on this.</td>', 'Very nice lightng on this.', '2002-05-06 17:03:00.000000', NULL, 1),
