(56848, 1363, 536, '<td valign="top">Nice. I enjoyed this photo. I feel it is well done.  Not overly interesting but a cool subject.  I don''t get the feeling that you''re trying to sell me anything. : )</td>', 'Nice. I enjoyed this photo. I feel it is well done.  Not overly interesting but a cool subject.  I don''t get the feeling that you''re trying to sell me anything. : )', '2002-05-07 22:10:00.000000', NULL, 1),
(56849, 1363, 714, '<td valign="top">Cool idea.  very creative.</td>', 'Cool idea.  very creative.', '2002-05-07 23:17:00.000000', NULL, 1),
