(57164, 1389, 748, '<td valign="top">Not sure if you are selling Vancouver as a vacation spot, but the photo is fantastic and I have rated it as such.</td>', 'Not sure if you are selling Vancouver as a vacation spot, but the photo is fantastic and I have rated it as such.', '2002-05-07 18:18:00.000000', NULL, 1),
(57165, 1389, 554, '<td valign="top">I just love watching the lights come on while it downloads. great picture but what are you selling?</td>', 'I just love watching the lights come on while it downloads. great picture but what are you selling?', '2002-05-07 18:42:00.000000', NULL, 1),
(57166, 1389, 1350, '<td valign="top">Truly a beautiful photo. I love the composition, lighting and reflection. Very well done! Without the title, however, I''m not sure I''d know what you were selling...</td>', 'Truly a beautiful photo. I love the composition, lighting and reflection. Very well done! Without the title, however, I''m not sure I''d know what you were selling...', '2002-05-07 18:53:00.000000', NULL, 1),
(57167, 1389, 661, '<td valign="top">Beautiful picture.  Great night shot.</td>', 'Beautiful picture.  Great night shot.', '2002-05-07 19:00:00.000000', NULL, 1),
(57168, 1389, 813, '<td valign="top">beautiful night shot, but I don''t see how it sells the idea of the title, none of these boats are sailing, maybe it just needs a better title. good picture though and I''ll score it based on photographic merits</td>', 'beautiful night shot, but I don''t see how it sells the idea of the title, none of these boats are sailing, maybe it just needs a better title. good picture though and I''ll score it based on photographic merits', '2002-05-07 20:28:00.000000', NULL, 1),
(57169, 1389, 875, '<td valign="top">Absolutely stunning!</td>', 'Absolutely stunning!', '2002-05-08 00:26:00.000000', NULL, 1),
(57170, 1389, 2, '<td valign="top">If I were convinced this was a product, this would be a ten.  The photographic and compositional quality of this photograph is absolutely amazing.  Great exposure.</td>', 'If I were convinced this was a product, this would be a ten.  The photographic and compositional quality of this photograph is absolutely amazing.  Great exposure.', '2002-05-08 00:26:00.000000', NULL, 1),
