(57181, 1389, 749, '<td valign="top">Beautiful shot, would make a great advert!</td>', 'Beautiful shot, would make a great advert!', '2002-05-11 09:05:00.000000', NULL, 1),
(57182, 1389, 1078, '<td valign="top">I think the picture might be a little "weak" for what you''re trying to sell -- I see ships docked, none sailing. HOWEVER, the picture is very nicely done.  I think maybe I would have cropped it at the 640x427 size to remove some of the extra blank sky and water -- but that''s very much a personal taste</td>', 'I think the picture might be a little "weak" for what you''re trying to sell -- I see ships docked, none sailing. HOWEVER, the picture is very nicely done.  I think maybe I would have cropped it at the 640x427 size to remove some of the extra blank sky and water -- but that''s very much a personal taste', '2002-05-12 15:18:00.000000', NULL, 1),
(57183, 1389, 811, '<td valign="top">My favorite pic this time.  This is absolutely gorgeous.  Next time, though, take a sling shot or bb gun and shoot out the lights that are so bright.  Ha Ha.  Even so, nice job. 10</td>', 'My favorite pic this time.  This is absolutely gorgeous.  Next time, though, take a sling shot or bb gun and shoot out the lights that are so bright.  Ha Ha.  Even so, nice job. 10', '2002-05-12 16:17:00.000000', NULL, 1),
(57184, 1389, 587, '<td valign="top">one word - beautiful.  (great photo)</td>', 'one word - beautiful.  (great photo)', '2002-05-12 20:21:00.000000', NULL, 1),
(57185, 1389, 1, '<td valign="top">Great shot, but as for selling sailboats, it''s not working.  I think a day shot of the sailboat in use would be key.</td>', 'Great shot, but as for selling sailboats, it''s not working.  I think a day shot of the sailboat in use would be key.', '2002-05-12 22:16:00.000000', NULL, 1),
(57186, 1389, 139, '<td valign="top">This is a really excellent shot.   I am quite impressed.  I''m anxious to see the technical details about the photo (shutter speed, aperature, etc).</td>', 'This is a really excellent shot.   I am quite impressed.  I''m anxious to see the technical details about the photo (shutter speed, aperature, etc).', '2002-05-12 23:27:00.000000', NULL, 1),
(57187, 1389, 1584, '<td valign="top">what a really pretty view!</td>', 'what a really pretty view!', '2002-05-13 00:13:00.000000', NULL, 1),
