(57197, 1391, 772, '<td valign="top">My system usually becomes unstable when i get into the vodka too!  I need a shirt that says "CTRL+ALT+DEL" to wear when i go out for a few drinks :)  Nice composition here... I like the crop you chose as well :)</td>', 'My system usually becomes unstable when i get into the vodka too!  I need a shirt that says "CTRL+ALT+DEL" to wear when i go out for a few drinks :)  Nice composition here... I like the crop you chose as well :)', '2002-05-06 12:42:00.000000', NULL, 1),
(57198, 1391, 718, '<td valign="top">Enough absolute!!!!!!!!</td>', 'Enough absolute!!!!!!!!', '2002-05-06 13:48:00.000000', NULL, 1),
