(57222, 1391, 1209, '<td valign="top">I decided to come back and look it over again. Raised your score considerably. Bottle is a nice sharp image.</td>', 'I decided to come back and look it over again. Raised your score considerably. Bottle is a nice sharp image.', '2002-05-09 21:57:00.000000', NULL, 1),
(57223, 1391, 1031, '<td valign="top">Maybe if you squirt a few drops of vodka into the "cereal port" ... I find the vertical reflection on the neck a little harsh and distracting (if not limited by DPC specs I''d crop off a little more); otherwise I like it a lot.</td>', 'Maybe if you squirt a few drops of vodka into the "cereal port" ... I find the vertical reflection on the neck a little harsh and distracting (if not limited by DPC specs I''d crop off a little more); otherwise I like it a lot.', '2002-05-10 15:38:00.000000', NULL, 1),
