(57432, 1401, 259, '<td valign="top">i really like this one, i had an idea along the same lines, but it didn''t submit a photo this week.  the best part about this picture is the perspective, good job.</td>', 'i really like this one, i had an idea along the same lines, but it didn''t submit a photo this week.  the best part about this picture is the perspective, good job.', '2002-05-06 14:24:00.000000', NULL, 1),
(57433, 1401, 813, '<td valign="top">I like the angle, and I think the shot would work better against a plain sky (no trees). It would also work better with flatter lighting.</td>', 'I like the angle, and I think the shot would work better against a plain sky (no trees). It would also work better with flatter lighting.', '2002-05-06 14:27:00.000000', NULL, 1),
(57434, 1401, 1485, '<td valign="top">I like the close up of the car.. the curvature of the hoodline and roofline are very appealing and give sort of a fish-eye feel to the picture.  Also, the color of the sky is washed in a way that works well with the car.</td>', 'I like the close up of the car.. the curvature of the hoodline and roofline are very appealing and give sort of a fish-eye feel to the picture.  Also, the color of the sky is washed in a way that works well with the car.', '2002-05-06 14:36:00.000000', NULL, 1),
