(57438, 1401, 661, '<td valign="top">Interesting reflection in the right light.</td>', 'Interesting reflection in the right light.', '2002-05-06 18:55:00.000000', NULL, 1),
(57439, 1401, 544, '<td valign="top">I like this shot. Very metallic and sleek - the sky matches the car and the trees frame the shot very nicely. The whole image looks smooth. nice framing of the car itself as well, and good positioning.</td>', 'I like this shot. Very metallic and sleek - the sky matches the car and the trees frame the shot very nicely. The whole image looks smooth. nice framing of the car itself as well, and good positioning.', '2002-05-06 19:52:00.000000', NULL, 1),
(57440, 1401, 459, '<td valign="top">I like the idea of the curb in front of the car.  It makes it look like a different car.  The monochromatic look is also nice.  Why did you photograph a dirty car, though?  Who would buy it?</td>', 'I like the idea of the curb in front of the car.  It makes it look like a different car.  The monochromatic look is also nice.  Why did you photograph a dirty car, though?  Who would buy it?', '2002-05-06 20:27:00.000000', NULL, 1),
