(57968, 1422, 1491, '<td valign="top">Creative idea. But I don''t like the dirty window as background. Also, I find the DOF too narrow.</td>', 'Creative idea. But I don''t like the dirty window as background. Also, I find the DOF too narrow.', '2002-05-07 02:33:00.000000', NULL, 1),
(57969, 1422, 888, '<td valign="top">hahahahahah I love it<br/>This is my challenge winner.<br/>Others may think its too much of a comedy entry to win but its got my vote.<br/>Maybe a little more light on the left side of the dirt but its great anyway</td>', 'hahahahahah I love itThis is my challenge winner.Others may think its too much of a comedy entry to win but its got my vote.Maybe a little more light on the left side of the dirt but its great anyway', '2002-05-07 04:40:00.000000', NULL, 1),
(57970, 1422, 1037, '<td valign="top">The thumbnail for this one made me laugh out loud, and seeing the full version makes me love it more :). It''s really nicely composed and photographed, and just overall funny in a cheeky way. A ten from me.</td>', 'The thumbnail for this one made me laugh out loud, and seeing the full version makes me love it more :). It''s really nicely composed and photographed, and just overall funny in a cheeky way. A ten from me.', '2002-05-07 05:23:00.000000', NULL, 1),
