(57978, 1422, 671, '<td valign="top">Very humorous!  Excellent subject, framing.  Good focus (a little blurry on the edge of the shell) I like the slant of the sign offsetting the slope of the edge of the shell.</td>', 'Very humorous!  Excellent subject, framing.  Good focus (a little blurry on the edge of the shell) I like the slant of the sign offsetting the slope of the edge of the shell.', '2002-05-07 21:45:00.000000', NULL, 1),
(57979, 1422, 536, '<td valign="top">cute (really)</td>', 'cute (really)', '2002-05-07 22:10:00.000000', NULL, 1),
(57980, 1422, 446, '<td valign="top">Very clever!  It would have made a great shot with bettter exposure to pull out more of the detail in the subject and focus to improve on the sharpness.  It appears to be taken in front of glass?  There is too much distraction from the flaws in the glass for my tastes.  Good effort nontheless.</td>', 'Very clever!  It would have made a great shot with bettter exposure to pull out more of the detail in the subject and focus to improve on the sharpness.  It appears to be taken in front of glass?  There is too much distraction from the flaws in the glass for my tastes.  Good effort nontheless.', '2002-05-07 22:30:00.000000', NULL, 1),
(57981, 1422, 714, '<td valign="top">lol, good one.</td>', 'lol, good one.', '2002-05-07 23:46:00.000000', NULL, 1),
