(58511, 1452, 1209, '<td valign="top">Original idea, good for a chuckle. Background is a little simplistic for this shot.</td>', 'Original idea, good for a chuckle. Background is a little simplistic for this shot.', '2002-05-08 23:52:00.000000', NULL, 1),
(58512, 1452, 543, '<td valign="top">I was pretty proud of myself for thinking of this as a solution to the ''no added text'' problem.  You should be, too.  Great idea, and, except for a slight blowout in the blindfold, very well photographed.  I can''t decide whether B/W was the right choice.  It does match the message, but I can''t help but thinking, since color is the easy way these days, if the kidnappers would have bothered with a conversion.</td>', 'I was pretty proud of myself for thinking of this as a solution to the ''no added text'' problem.  You should be, too.  Great idea, and, except for a slight blowout in the blindfold, very well photographed.  I can''t decide whether B/W was the right choice.  It does match the message, but I can''t help but thinking, since color is the easy way these days, if the kidnappers would have bothered with a conversion.', '2002-05-09 05:27:00.000000', NULL, 1),
(58513, 1452, 714, '<td valign="top">Very creative and funny.</td>', 'Very creative and funny.', '2002-05-09 10:07:00.000000', NULL, 1),
