(59569, 1502, 671, '<td valign="top">nice arrangement, too much glare</td>', 'nice arrangement, too much glare', '2002-05-06 20:38:00.000000', NULL, 1),
(59570, 1502, 724, '<td valign="top">There are never enough blue ones!  I love the color here, the bottom right is distracting.   I am curious why you decided not to freeze them and have them be all frosty?....8</td>', 'There are never enough blue ones!  I love the color here, the bottom right is distracting.   I am curious why you decided not to freeze them and have them be all frosty?....8', '2002-05-06 20:53:00.000000', NULL, 1),
