(59572, 1502, 1037, '<td valign="top">Oooh, pretty colours :) The strong reflections of the lights on the plastic is a bit distracting though.</td>', 'Oooh, pretty colours :) The strong reflections of the lights on the plastic is a bit distracting though.', '2002-05-07 03:11:00.000000', NULL, 1),
(59573, 1502, 888, '<td valign="top">I think it''d be better if they were frozen, maybe a bit of ice and water would have looked cool</td>', 'I think it''d be better if they were frozen, maybe a bit of ice and water would have looked cool', '2002-05-07 04:33:00.000000', NULL, 1),
(59574, 1502, 1054, '<td valign="top">Beautiful!  I''m giving this a 9, if the pops continued through the corner, I''d have given it a 10.</td>', 'Beautiful!  I''m giving this a 9, if the pops continued through the corner, I''d have given it a 10.', '2002-05-07 13:25:00.000000', NULL, 1),
(59575, 1502, 215, '<td valign="top">Close the aperture more (increase the f/number) to make everything in-focus.</td>', 'Close the aperture more (increase the f/number) to make everything in-focus.', '2002-05-07 21:31:00.000000', NULL, 1),
