(59599, 1503, 92, '<td valign="top">I can''t wait to see who this photo belongs to ! haha Where''s the strawberries?</td>', 'I can''t wait to see who this photo belongs to ! haha Where''s the strawberries?', '2002-05-06 06:53:00.000000', NULL, 1),
