(58920, 1467, 637, '<td valign="top">Wish the lettering towards the bottom of the bottle was sharper.</td>', 'Wish the lettering towards the bottom of the bottle was sharper.', '2002-05-12 23:37:00.000000', NULL, 1),
(58921, 1467, 139, '<td valign="top">Did you try rotating -pi/2?  I suppose you wanted the name to be readable.  In that case, better focus would have helped.  Good job, though.</td>', 'Did you try rotating -pi/2?  I suppose you wanted the name to be readable.  In that case, better focus would have helped.  Good job, though.', '2002-05-12 23:41:00.000000', NULL, 1),
(58922, 1467, 749, '<td valign="top">For those of you who asked, yes, black vodka really does exist, and it''s very nice too! :o)<br/><br/>US site - www.blackvodka.com<br/>UK site - www.blavod.com<br/><br/>They use a herb to stain it a very dark green, nearly black, and it makes the vodka just a tiny bit smoother :o) Enough of the plug, back to the photo! The shot was light by sunlight alone, but I was playing about with aperture &amp; shutter settings, so ended up with a very blue shot. I got most of it black by readjusting the levels, but couldn''t get it as dark as I had hoped, hence its a bit over exposed looking. The focus was a pain, as I wasn''t able to get the depth I wanted, so I went with the focus on the ''pure black vodka'', since that''s what I was trying to sell.<br/><br/>Final thing - the reason this doesn''t show any more of the bottle or its enjoyment was that I was trying to sell the name, ie create brand awareness, rather than the physical product.<br/><br/>Thanks for all your comments!</td>', 'For those of you who asked, yes, black vodka really does exist, and it''s very nice too! :o)US site - www.blackvodka.comUK site - www.blavod.comThey use a herb to stain it a very dark green, nearly black, and it makes the vodka just a tiny bit smoother :o) Enough of the plug, back to the photo! The shot was light by sunlight alone, but I was playing about with aperture & shutter settings, so ended up with a very blue shot. I got most of it black by readjusting the levels, but couldn''t get it as dark as I had hoped, hence its a bit over exposed looking. The focus was a pain, as I wasn''t able to get the depth I wanted, so I went with the focus on the ''pure black vodka'', since that''s what I was trying to sell.Final thing - the reason this doesn''t show any more of the bottle or its enjoyment was that I was trying to sell the name, ie create brand awareness, rather than the physical product.Thanks for all your comments!', '2002-05-14 16:33:00.000000', NULL, 0),
(58923, 1468, 1204, '<td valign="top">I can''t really pinpoint what it is - but this picture is brilliant.  Sell it to Pepsi!</td>', 'I can''t really pinpoint what it is - but this picture is brilliant.  Sell it to Pepsi!', '2002-05-06 16:33:00.000000', NULL, 1),
